import re

def replace_nums_reverse_words(input_string, punctuation=False):
    """Develop a Python script that not only substitutes all numeric characters in a string with asterisks, but also reverses the order of the words in the edited string. Additionally, ensure your script can handle a multiline string input where each line is treated separately. Your script should provide an option for the user to choose whether to include punctuation in the reversed order or not. Include unit tests to validate your solution."""
    lines = input_string.split("\n")
    resulting_lines = []

    for line in lines:
        # Replace digits with asterisks
        line = re.sub("\d", "*", line) 

        if punctuation:  
            words = re.findall(r'\b\w+\b', line)
            other_chars = re.split(r'\b\w+\b', line)
            reversed_line = ''.join([w + c for w, c in zip(words[::-1], other_chars[::-1])] + other_chars[len(words):])
        else:  
            words = line.split()
            reversed_line = ' '.join(words[::-1])

        resulting_lines.append(reversed_line)

    return "\n".join(resulting_lines)


