int shortestDistance(int grid[MAX][MAX], int m, int n) {
    int total_count[MAX][MAX] = {0};
    int dist_sum[MAX][MAX] = {0};
    int house_count = 0;
    int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (grid[i][j] == 1) {
                house_count++;
                int q[MAX * MAX][2];
                int front = 0;
                int rear = 0;
                bool visited[MAX][MAX] = {false};
                int level = 1;
                q[rear][0] = i;
                q[rear][1] = j;
                rear++;
                visited[i][j] = true;
                while (front < rear) {
                    int size = rear - front;
                    for (int k = 0; k < size; k++) {
                        int x = q[front][0];
                        int y = q[front][1];
                        front++;
                        for (int l = 0; l < 4; l++) {
                            int x_new = x + dirs[l][0];
                            int y_new = y + dirs[l][1];
                            if (x_new >= 0 && x_new < m && y_new >= 0 && y_new < n && !visited[x_new][y_new] && grid[x_new][y_new] == 0) {
                                visited[x_new][y_new] = true;
                                q[rear][0] = x_new;
                                q[rear][1] = y_new;
                                rear++;
                                dist_sum[x_new][y_new] += level;
                                total_count[x_new][y_new]++;
                            }
                        }
                    }
                    level++;
                }
            }
        }
    }

    int min_dist = INT_MAX;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (total_count[i][j] == house_count) {
                min_dist = (min_dist < dist_sum[i][j]) ? min_dist : dist_sum[i][j];
            }
        }
    }

    return (min_dist == INT_MAX) ? -1 : min_dist;
}

