    """port this code from ANSI C to python:
```c
#include <stdio.h>
#include <stdlib.h>
#include <math.h>

int* water_flow(int* heights, int n, int volume, int k, int* returnSize){
    int left = k;
    int right = k;
    int* water = (int*)calloc(n, sizeof(int));
    water[k] = volume;

    while(1){
        // move left
        while(left > 0 && heights[left-1] + water[left-1] <= heights[left] + water[left]){
            left--;
        }
        // move right
        while(right < n-1 && heights[right+1] + water[right+1] <= heights[right] + water[right]){
            right++;
        }

        // check if done
        if(left == 0 && right == n-1){
            break;
        }

        // find lowest point
        int lowest = left;
        for(int i=left+1; i<=right; i++){
            if(heights[i] + water[i] < heights[lowest] + water[lowest]){
                lowest = i;
            }
        }

        // fill lowest point
        int diff = heights[lowest] + water[lowest] - (heights[lowest-1] + water[lowest-1]);
        for(int i=lowest-1; i>=left; i--){
            water[i] += diff;
        }

        diff = heights[lowest] + water[lowest] - (heights[lowest+1] + water[lowest+1]);
        for(int i=lowest+1; i<=right; i++){
            water[i] += diff;
        }
    }

    *returnSize = n;
    int* result = (int*)calloc(n, sizeof(int));
    for(int i=0; i<n; i++){
        result[i] = heights[i] + water[i];
    }
    free(water);
    return result;
