    """port this code to python:
```R
min_minutes <- function(s, k) {
  n <- nchar(s)
  left_counts <- c(0, 0, 0)
  right_counts <- c(0, 0, 0)
  for (c in strsplit(s, "")[[1]]) {
    right_counts[utf8ToInt(c) - utf8ToInt("a") + 1] <- right_counts[utf8ToInt(c) - utf8ToInt("a") + 1] + 1
  }

  ans <- n
  total <- 0
  l <- 1
  r <- n
  while (l < r) {
    while ((l < r) & (left_counts[utf8ToInt(substr(s, l, l)) - utf8ToInt("a") + 1] < k) & (right_counts[utf8ToInt(substr(s, r, r)) - utf8ToInt("a") + 1] < k)) {
      need_left <- max(0, k - left_counts[utf8ToInt(substr(s, l, l)) - utf8ToInt("a") + 1])
      need_right <- max(0, k - right_counts[utf8ToInt(substr(s, r, r)) - utf8ToInt("a") + 1])
      if (need_left <= need_right) {
        total <- total + need_left
        l <- l + 1
        left_counts[utf8ToInt(substr(s, l, l)) - utf8ToInt("a") + 1] <- left_counts[utf8ToInt(substr(s, l, l)) - utf8ToInt("a") + 1] + 1
        right_counts[utf8ToInt(substr(s, l, l)) - utf8ToInt("a") + 1] <- right_counts[utf8ToInt(substr(s, l, l)) - utf8ToInt("a") + 1] - 1
      } else {
        total <- total + need_right
        r <- r - 1
        right_counts[utf8ToInt(substr(s, r, r)) - utf8ToInt("a") + 1] <- right_counts[utf8ToInt(substr(s, r, r)) - utf8ToInt("a") + 1] - 1
        left_counts[utf8ToInt(substr(s, r, r)) - utf8ToInt("a") + 1] <- left_counts[utf8ToInt(substr(s, r, r)) - utf8ToInt("a") + 1] + 1
      }
    }
    ans <- min(ans, total)
    if (l + 1 < n) {
      total <- total - left_counts[utf8ToInt(substr(s, l, l)) - utf8ToInt("a") + 1]
      left_counts[utf8ToInt(substr(s, l, l)) - utf8ToInt("a") + 1] <- left_counts[utf8ToInt(substr(s, l, l)) - utf8ToInt("a") + 1] - 1
      right_counts[utf8ToInt(substr(s, l+1, l+1)) - utf8ToInt("a") + 1] <- right_counts[utf8ToInt(substr(s, l+1, l+1)) - utf8ToInt("a") + 1] + 1
      l <- l + 1
    } else {
      break
    }
  }
  if ((left_counts[1] >= k) & (left_counts[2] >= k) & (left_counts[3] >= k)) {
    return(ans)
  } else {
    return(-1)
  }
}
```"""

